class Solution {
    public int maxPoints(int[][] points) {
        int length = points.length;
        if (length <= 2) {
            return length;
        }
        int best = 2;
        for (int first = 0; first < length; first++) {
            for (int second = first + 1; second < length; second++) {
                int count = 0;
                long dx = (long) points[second][0] - points[first][0];
                long dy = (long) points[second][1] - points[first][1];
                for (int candidate = 0; candidate < length; candidate++) {
                    long candidateX = (long) points[candidate][0] - points[first][0];
                    long candidateY = (long) points[candidate][1] - points[first][1];
                    if (dx * candidateY == dy * candidateX) {
                        count++;
                    }
                }
                best = Math.max(best, count);
            }
        }
        return best;
    }
}

