import java.util.HashMap;
import java.util.Map;

class Solution {
    public int maxPoints(int[][] points) {
        int length = points.length;
        int best = Math.min(length, 2);
        for (int anchor = 0; anchor < length; anchor++) {
            Map<String, Integer> directions = new HashMap<>();
            int duplicates = 1;
            int localBest = 0;
            for (int other = anchor + 1; other < length; other++) {
                int dx = points[other][0] - points[anchor][0];
                int dy = points[other][1] - points[anchor][1];
                if (dx == 0 && dy == 0) {
                    duplicates++;
                    continue;
                }
                int divisor = gcd(Math.abs(dx), Math.abs(dy));
                dx /= divisor;
                dy /= divisor;
                if (dx < 0 || (dx == 0 && dy < 0)) {
                    dx = -dx;
                    dy = -dy;
                }
                String direction = dy + "/" + dx;
                int count = directions.getOrDefault(direction, 0) + 1;
                directions.put(direction, count);
                localBest = Math.max(localBest, count);
            }
            best = Math.max(best, localBest + duplicates);
        }
        return best;
    }

    private int gcd(int first, int second) {
        while (second != 0) {
            int remainder = first % second;
            first = second;
            second = remainder;
        }
        return first;
    }
}
